package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type PartRec struct { // 01 PART-REC, 15 bytes
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

// Standalone working-storage items
var WsEofFlag string = "N"                         // PIC X len=1 = "N"
var WsLabel string = "                    "        // PIC X(20) len=20 = SPACES
var WsACount int64 = 0                            // PIC 99 len=2 = 0
var WsTotalA int64 = 0                            // PIC 999 len=3 = 0
var WsCount int64 = 0                             // PIC 999 len=3 = 0

var partRec PartRec
var partFile *os.File
var scanner *bufio.Scanner

func truncateToDigits(val int64, digits int) int64 {
	if digits <= 0 {
		return 0
	}
	pow := int64(1)
	for i := 0; i < digits; i++ {
		pow *= 10
	}
	return val % pow
}

func formatPic(val int64, digits int) string {
	v := truncateToDigits(val, digits)
	if v < 0 {
		v = -v
	}
	return fmt.Sprintf("%0*d", digits, v)
}

func effectiveString(s string, delimitedBySize bool) string {
	if delimitedBySize {
		return s
	}
	idx := strings.Index(s, " ")
	if idx == -1 {
		return s
	}
	return s[:idx]
}

func readPara() {
	if scanner == nil {
		WsEofFlag = "Y"
		return
	}
	if scanner.Scan() {
		line := scanner.Text()
		if len(line) > 15 {
			line = line[:15]
		} else if len(line) < 15 {
			line = line + strings.Repeat(" ", 15-len(line))
		}
		partRec.LbPart = line[0:8]
		partRec.LbRegion = line[8:11]
		serialStr := line[11:15]
		t := strings.TrimSpace(serialStr)
		if t == "" {
			partRec.LbSerial = 0
		} else {
			isDigits := true
			for _, c := range t {
				if c < '0' || c > '9' {
					isDigits = false
					break
				}
			}
			if isDigits {
				v, _ := strconv.ParseInt(t, 10, 64)
				partRec.LbSerial = truncateToDigits(v, 4)
			} else {
				partRec.LbSerial = 0
			}
		}
	} else {
		if err := scanner.Err(); err != nil {
			fmt.Fprintf(os.Stderr, "read error: %v\n", err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func processPara() {
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	cnt := strings.Count(partRec.LbPart, "A")
	WsACount = truncateToDigits(int64(cnt), 2)

	regionEff := effectiveString(partRec.LbRegion, false)
	partEff := effectiveString(partRec.LbPart, false)
	serialEff := formatPic(partRec.LbSerial, 4)

	target := []byte(strings.Repeat(" ", 20))
	pos := 0
	copyStr := func(s string) {
		for i := 0; i < len(s); i++ {
			if pos >= 20 {
				break
			}
			target[pos] = s[i]
			pos++
		}
	}
	copyStr(regionEff)
	copyStr("-")
	copyStr(partEff)
	copyStr("-")
	copyStr(serialEff)
	WsLabel = string(target)

	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")

	WsTotalA = truncateToDigits(WsTotalA+WsACount, 3)
	WsCount = truncateToDigits(WsCount+1, 3)

	line := WsLabel + " A=" + formatPic(WsACount, 2) + "\n"
	os.Stdout.WriteString(line)

	readPara()
}

func summaryPara() {
	line := "LABELS: " + formatPic(WsCount, 3) + " A-TOTAL: " + formatPic(WsTotalA, 3) + "\n"
	os.Stdout.WriteString(line)
}

func mainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			scanner = nil
			partFile = nil
		} else {
			fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
			os.Exit(1)
		}
	} else {
		partFile = f
		scanner = bufio.NewScanner(f)
		const maxCap = 256 * 1024
		buf := make([]byte, 0, 64*1024)
		scanner.Buffer(buf, maxCap)
	}

	readPara()
	for WsEofFlag != "Y" {
		processPara()
	}
	if partFile != nil {
		partFile.Close()
	}
	summaryPara()
}

func main() {
	mainPara()
}
